// Shared contracts for the AgentHelpDesk backend (product/).
// These types ARE the contract between modules. Do not edit this file without
// writing a request to product/CONTRACT_REQUESTS.md — the orchestrator owns it.
//
// Erasable-syntax-only (Node type-stripping): no enums, namespaces, decorators,
// or constructor parameter properties. Use `import type` for type-only imports.
// Import modules with an explicit `.ts` extension.

export type Mode = 'auto' | 'approve_first' | 'suggest_only';
export type FailureClass = 'knowledge' | 'code' | 'authority';
export type CaseStage =
  | 'opened'
  | 'reproducing'
  | 'fix_drafted'
  | 'proving'
  | 'awaiting_approval'
  | 'answered'
  | 'shipped'
  | 'closed'
  | 'escalated';

export interface Proofs {
  replay: boolean;
  vendor_tests: boolean;
  fresh_agent: boolean;
}

export interface Envelope {
  verbs: string[];
  cap_usd: number;
  per_user: number;
}

export interface Grant {
  id: string;
  failure_id: string;
  verb: string;
  envelope: Envelope;
  idempotency_key: string;
  receipt: string;
  spent: boolean;
  created_at: string;
}

export interface Vendor {
  id: string;
  name: string;
  repo_url: string;
  sandbox_name: string;
  risk_policy: Mode;
  stripe_customer_id: string;
  payer_mode: 'vendor' | 'agent';
  report_contacts: string[];
  /** The vendor's own test suite, run inside its sandbox for the vendor_tests
   * proof. Operator-set only — never taken from inbound report data. Falls back
   * to the sandbox file `/ahd/test-command`, then to `npm test`. */
  test_command?: string;
  /** Which agent-pays rail this vendor chose. Absent means the default in
   * billing/billable.ts chooseLane (`payer_mode === 'agent'` → `b2b_mpp`). */
  agent_pay_rail?: 'mpp' | 'x402';
  /** Operator-set: this vendor is never billed. The only exemption that applies
   * when the AGENT pays — free-text privacy matching is not honored on the
   * agent-pays lanes, or an agent could dodge a bill by writing "gdpr" into its
   * task string. */
  billing_exempt?: boolean;
}

export interface Failure {
  id: string;
  vendor_id: string;
  agent_id: string;
  task: string;
  request: unknown;
  response: unknown;
  klass: FailureClass;
  status: CaseStage;
  ack_by: string;
  resolve_by: string;
  queue_position: number;
  created_at: string;
  /** Handle on the channel the case arrived on (an email thread id, a webhook
   * delivery id). Lets any module route a reply back on the originating thread
   * without importing that channel's internals. Null for MCP/web cases. */
  channel_ref?: string | null;
}

export interface Attempt {
  id: string;
  failure_id: string;
  diff: string;
  proof_replay: boolean;
  proof_vendor_tests: boolean;
  proof_fresh_agent: boolean;
  log_url: string;
}

export interface Outcome {
  id: string;
  failure_id: string;
  shipped_as: 'answer' | 'pr' | 'grant' | 'regression';
  approved_by: string | null;
  agent_retry_ok: boolean;
  billable: boolean;
  payer: 'vendor' | 'agent' | null;
  stripe_event_id: string | null;
  mpp_payment_id: string | null;
  x402_payment_id: string | null;
  /** When the outcome was recorded. Optional so older rows stay valid; reports
   * fall back to the case's `Failure.created_at` when it is missing. */
  created_at?: string;
}

export interface ToolEvent {
  id: string;
  ticket_id: string;
  stage: string;
  tool: string;
  action: string;
  t_ms: number;
  d_ms: number;
  result: string;
  payload: unknown;
  at: string;
}

export interface MeterEvent {
  id: string;
  outcome_id: string;
  event_name: string;
  identifier: string;
  value: number;
  mode: 'test' | 'live';
  at: string;
}

export interface ApprovalRequest {
  id: string;
  failure_id: string;
  change_summary: string;
  channel: 'text' | 'email';
  sent_at: string;
  replied_at: string | null;
  decision: 'yes' | 'no' | null;
  approver: string;
}

/** The structured reply handed back to the failing agent (RFC 9457-shaped + proofs). */
export interface AgentReply {
  type: string;
  title: string;
  status: number;
  retryable: boolean;
  fix_steps: string[];
  snippet: string;
  tested: Proofs;
  regression_test_id: string;
  case_id: string;
  ack_by: string;
  resolve_by: string;
  queue_position: number;
  outcome?: unknown;
  authority?: Envelope;
  events: string[];
  audit_receipt: string;
}

// ---- Sandbox (Blaxel) ----
export interface ExecResult {
  stdout: string;
  stderr: string;
  exit_code: number;
}
export interface SandboxHandle {
  name: string;
  exec(cmd: string, opts?: { timeout_ms?: number; background?: boolean }): Promise<ExecResult>;
  write(path: string, content: string): Promise<void>;
  read(path: string): Promise<string>;
  snapshot(): Promise<string>;
}
export interface SandboxRunner {
  createOrResume(name: string): Promise<SandboxHandle>;
  fork(snapshotId: string, newName: string): Promise<SandboxHandle>;
  destroy(name: string): Promise<void>;
}

// ---- Proofs ----
export type ProofName = keyof Proofs;
export interface ProofResult {
  proof: ProofName;
  pass: boolean;
  detail: string;
}
export interface ProofRunner {
  replay(sb: SandboxHandle, f: Failure): Promise<ProofResult>;
  vendorTests(sb: SandboxHandle): Promise<ProofResult>;
  freshAgent(sb: SandboxHandle, task: string, changed: string[]): Promise<ProofResult>;
}

// ---- Billing (Stripe) ----
export type PayLane = 'b2b_meter' | 'a2a_x402' | 'b2b_mpp';
export interface BillableDecision {
  billable: boolean;
  reason: string;
  lane: PayLane | null;
}

// ---- Intake report (what an agent or channel sends) ----
export interface ProblemReport {
  vendor_hint?: string;
  agent_id: string;
  task: string;
  request: unknown;
  response: unknown;
  klass?: FailureClass;
  channel: 'mcp' | 'email' | 'webhook' | 'forwarded';
  /** Caller-supplied replay key. When present the case id is derived from it, so
   * a provider retry returns the same case instead of opening a second one. */
  idempotency_key?: string;
  /** Channel-side handle (an email thread id, a webhook delivery id) copied onto
   * the Failure so any module can reply on the originating thread. */
  channel_ref?: string | null;
}
